264→use chrono::Utc;
265→use spectraplex_core::materializer::{DatasetDescriptor, DatasetName, Materializer, TokenTransfer};
266→use spectraplex_core::v2::ChainFamily;
267→use uuid::Uuid;
268→
269→/// Extract ERC-20 token transfers from an EVM raw transaction.
270→///
271→/// Decodes Transfer(address,address,uint256) events from raw log topics/data.
272→/// Does not filter by wallet — emits all transfers found in the transaction.
273→pub fn extract_evm_token_transfers(
274→    raw_tx_id: Option<Uuid>,
275→    network: &str,
276→    raw_metadata: &serde_json::Value,
277→) -> Vec<TokenTransfer> {
278→    let mut transfers = Vec::new();
279→
280→    let topics = match raw_metadata.get("topics").and_then(|t| t.as_array()) {
281→        Some(t) => t,
282→        None => return vec![],
283→    };
284→
285→    let topic0 = match topics.first().and_then(|t| t.as_str()) {
286→        Some(t) => t,
287→        None => return vec![],
288→    };
289→
290→    if topic0 != ERC20_TRANSFER_TOPIC || topics.len() < 3 {
291→        return vec![];
292→    }
293→
294→    let from = topic_to_address(topics[1].as_str().unwrap_or_default());
295→    let to = topic_to_address(topics[2].as_str().unwrap_or_default());
296→
297→    let data_hex = raw_metadata
298→        .get("data")
299→        .and_then(|d| d.as_str())
300→        .unwrap_or("0x0");
301→    let amount_bd = hex_to_bigdecimal(data_hex);
302→
303→    let token_address = raw_metadata
304→        .get("address")
305→        .and_then(|a| a.as_str())
306→        .unwrap_or("unknown")
307→        .to_string();
308→
309→    let decimals = token_decimals(&token_address);
310→    let symbol = token_symbol(&token_address);
311→    let normalized = normalize_bigdecimal(amount_bd, decimals);
312→
313→    transfers.push(TokenTransfer {
314→        id: Uuid::new_v4(),
315→        raw_transaction_id: raw_tx_id,
316→        network: network.to_string(),
317→        token_address,
318→        token_symbol: Some(symbol),
319→        from_address: from,
320→        to_address: to,
321→        amount: normalized,
322→        decimals: decimals as i32,
323→        dataset_version_id: None,
324→        created_at: Utc::now(),
325→    });
326→
327→    transfers
328→}
