        id: row.try_get("id")?,
        kind: sql_to_target_kind(&kind_str)?,
        network: row.try_get("network")?,
        chain_family: sql_to_chain_family(&family_str)?,
        address: row.try_get("address")?,
        filter_spec: row.try_get("filter_spec")?,
