214→   214→/// Build a batch INSERT for `raw_transactions` with ON CONFLICT DO NOTHING.
215→   215→pub fn build_raw_transaction_insert(
216→   216→    txs: &[RawTransaction],
217→   217→) -> anyhow::Result<(String, sqlx::postgres::PgArguments)> {
218→   218→    let mut query = String::from(
219→   219→        "INSERT INTO raw_transactions \
220→   220→         (id, network, tx_hash, timestamp, block_number, raw_metadata, source, ingestion_run_id, ingested_at) \
221→   221→         VALUES ",
222→   222→    );
223→   223→    let mut args = sqlx::postgres::PgArguments::default();
224→   224→    for (i, tx) in txs.iter().enumerate() {
225→   225→        let base = i * 9;
226→   226→        if i > 0 {
227→   227→            query.push_str(", ");
228→   228→        }
229→   229→        query.push_str(&format!(
230→   230→            "(${}, ${}, ${}, ${}, ${}, ${}, ${}, ${}, ${})",
231→   231→            base + 1,
232→   232→            base + 2,
233→   233→            base + 3,
234→   234→            base + 4,
235→   235→            base + 5,
236→   236→            base + 6,
237→   237→            base + 7,
238→   238→            base + 8,
239→   239→            base + 9,
240→   240→        ));
241→   241→        use sqlx::Arguments;
242→   242→        args.add(tx.id).map_err(|e| anyhow::anyhow!("{e}"))?;
243→   243→        args.add(&tx.network).map_err(|e| anyhow::anyhow!("{e}"))?;
244→   244→        args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
245→   245→        args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
246→   246→        args.add(tx.block_number)
247→   247→            .map_err(|e| anyhow::anyhow!("{e}"))?;
248→   248→        args.add(&tx.raw_metadata)
249→   249→            .map_err(|e| anyhow::anyhow!("{e}"))?;
250→   250→        args.add(&tx.source).map_err(|e| anyhow::anyhow!("{e}"))?;
251→   251→        args.add(tx.ingestion_run_id)
252→   252→            .map_err(|e| anyhow::anyhow!("{e}"))?;
253→   253→        args.add(tx.ingested_at)
254→   254→            .map_err(|e| anyhow::anyhow!("{e}"))?;
255→   255→    }
256→   256→    query.push_str(" ON CONFLICT (network, tx_hash) DO NOTHING");
257→   257→    Ok((query, args))
258→   258→}
