            6
        ); // USDC
        assert_eq!(
            token_decimals("0xdac17f958d2ee523a2206206994597c13d831ec7"),
            6
        ); // USDT
        assert_eq!(
            token_decimals("0x2260fac5e5542a773aa44fbcfedf7c193bc2c599"),
            8
        ); // WBTC
