                "topics": [ERC20_TRANSFER_TOPIC, &from_padded, &to_padded],
                "data": "0x0000000000000000000000000000000000000000000000000de0b6b3a7640000",
                "address": "0xdac17f958d2ee523a2206206994597c13d831ec7",
            }),
