        assert_eq!(t.to_address, "0x2222222222222222222222222222222222222222");
        assert_eq!(t.token_symbol, Some("USDC".to_string()));
        assert_eq!(t.decimals, 6);
        assert_eq!(t.network, "ethereum-mainnet");
