                "value": "0x0",
                "from": "0x1111111111111111111111111111111111111111",
                "to": wallet,
            }),
        };

        // Second log: same tx hash, no gas fields (adapter omits them)
        let second_log = Transaction {
            id: Uuid::new_v4(),
