             FROM raw_transactions WHERE network = $1 AND tx_hash = $2",
        )
        .bind(network)
        .bind(tx_hash)
        .fetch_optional(self.pool())
        .await?;
        row.as_ref().map(row_to_raw_transaction).transpose()
    }

