    pub async fn update_ingestion_run_status(
        &self,
        id: Uuid,
        status: &str,
        finished_at: Option<DateTime<Utc>>,
        records_written: i64,
        error_message: Option<&str>,
    ) -> anyhow::Result<()> {
        sqlx::query(
            "UPDATE ingestion_runs SET status = $2, finished_at = $3, \
             records_written = $4, error_message = $5 WHERE id = $1",
