        args.add(tx.id).map_err(|e| anyhow::anyhow!("{e}"))?;
        args.add(&tx.network).map_err(|e| anyhow::anyhow!("{e}"))?;
        args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
        args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
